BEGIN;
DROP INDEX IF EXISTS portal_one_account_per_team;
ALTER TABLE portal_accounts DROP CONSTRAINT IF EXISTS portal_accounts_role_check;
ALTER TABLE portal_accounts DROP CONSTRAINT IF EXISTS portal_accounts_check;
UPDATE portal_accounts SET role='member' WHERE role='team';
ALTER TABLE portal_accounts ADD CONSTRAINT portal_accounts_role_check CHECK(role IN ('member','moderator','administrator'));
ALTER TABLE portal_accounts ADD CONSTRAINT portal_accounts_team_check CHECK(role<>'member' OR team_id IS NOT NULL);
ALTER TABLE portal_accounts ADD COLUMN display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=80);
ALTER TABLE portal_accounts ADD COLUMN owner boolean NOT NULL DEFAULT false;
UPDATE portal_accounts SET owner=true,display_name='Mike Walach' WHERE subject='user_3Kcbefcm3FvSHWAIYkQHjQu2WHo' AND role='administrator';
UPDATE portal_accounts SET display_name='ASCEND Test Member A' WHERE subject='user_3Kcd5swTp4c7BtxBLO6KnxV4zfL';
UPDATE portal_accounts SET display_name='ASCEND Test Member B' WHERE subject='user_3KcdEjBvP8Y2Ncx69VdcryeSXqd';
CREATE INDEX portal_accounts_team_idx ON portal_accounts(team_id);
ALTER TABLE missions ADD COLUMN publication_blocked boolean NOT NULL DEFAULT false;
CREATE TABLE discussion_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),description text NOT NULL DEFAULT '' CHECK(length(description)<=1000),created_by text NOT NULL REFERENCES portal_accounts(subject),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX discussion_group_name_idx ON discussion_groups(lower(name));
CREATE TABLE discussion_topics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),group_id uuid NOT NULL REFERENCES discussion_groups(id),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160),created_by text NOT NULL REFERENCES portal_accounts(subject),created_at timestamptz NOT NULL DEFAULT now(),pinned boolean NOT NULL DEFAULT false,locked boolean NOT NULL DEFAULT false,hidden boolean NOT NULL DEFAULT false);
CREATE INDEX discussion_topics_group_idx ON discussion_topics(group_id,pinned,created_at,id);
CREATE TABLE discussion_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_id uuid NOT NULL REFERENCES discussion_topics(id),author text NOT NULL REFERENCES portal_accounts(subject),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 8000),created_at timestamptz NOT NULL DEFAULT now(),hidden boolean NOT NULL DEFAULT false);
CREATE INDEX discussion_posts_topic_idx ON discussion_posts(topic_id,created_at,id);
CREATE INDEX discussion_posts_author_idx ON discussion_posts(author,created_at);
GRANT SELECT,INSERT ON discussion_groups,discussion_topics,discussion_posts TO ascend_runtime;
GRANT UPDATE(pinned,locked,hidden,group_id) ON discussion_topics TO ascend_runtime;
GRANT UPDATE(hidden) ON discussion_posts TO ascend_runtime;
GRANT UPDATE(role,team_id,display_name) ON portal_accounts TO ascend_runtime;
GRANT UPDATE(publication_blocked) ON missions TO ascend_runtime;
INSERT INTO discussion_groups(name,description,created_by) SELECT name,description,'user_3Kcbefcm3FvSHWAIYkQHjQu2WHo' FROM (VALUES
('Introductions','Meet other ASCEND members and teams.'),('Project updates','Share progress, field experiences and lessons learned.'),('Data loggers','Discuss logging hardware, firmware and data formats.'),('Ballooning','High-altitude balloon projects and questions.'),('Drones','UAS projects and questions.'),('Troubleshooting','Ask questions and help fellow members.')) AS seed(name,description);
INSERT INTO ascend_schema_migrations(version) VALUES(5);
COMMIT;
SELECT version FROM ascend_schema_migrations ORDER BY version;
